/* Raw/expanded compiler diagnostic transport budgets must never erase errors. */
#define _POSIX_C_SOURCE 200809L
#include "apx_frontend.h"
#include "../runtime/apx_runtime.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
static void save(const char *path,const char *text){FILE *f=fopen(path,"wb");assert(f);assert(fwrite(text,1,strlen(text),f)==strlen(text));assert(!fclose(f));}
static char *load(const char *path){FILE *f=fopen(path,"rb");assert(f);assert(!fseek(f,0,SEEK_END));long length=ftell(f);assert(length>=0&&length<16*1024*1024);rewind(f);char *text=calloc(1,(size_t)length+1);assert(text&&fread(text,1,(size_t)length,f)==(size_t)length);assert(!fclose(f));return text;}
static char *invoke(const char *mode,const char *source,const char *directory,int exit_code){char in[4096],out[4096];snprintf(in,sizeof in,"%s/source",directory);snprintf(out,sizeof out,"%s/output",directory);save(in,source);fflush(NULL);pid_t pid=fork();assert(pid>=0);if(!pid){assert(freopen(out,"wb",stdout));if(!strcmp(mode,"mcp")){assert(freopen(in,"rb",stdin));execl("bin/apx-mcp","bin/apx-mcp",(char*)NULL);}else execl("bin/apodexis","bin/apodexis",mode,in,"--json",(char*)NULL);_exit(127);}int status;assert(waitpid(pid,&status,0)==pid&&WIFEXITED(status)&&WEXITSTATUS(status)==exit_code);return load(out);}
static ApxValue *result_at(const char *all,int id){const char *begin=all;while(*begin){const char *end=strchr(begin,'\n');assert(end);ApxValue *row=apx_json_parse(begin,(size_t)(end-begin));assert(row);if(apx_json_integer(apx_json_get(row,"id"))==id){assert(!apx_json_get(row,"error"));return apx_json_get(row,"result");}begin=end+1;}assert(!"missing result");return NULL;}
static void check_diagnostics(ApxValue *response,size_t full,int incomplete){assert(response&&!strcmp(apx_json_string(apx_json_get(response,"status")),"error"));ApxValue *diagnostics=apx_json_get(response,"diagnostics");assert(diagnostics&&apx_json_kind(diagnostics)==5&&apx_json_length(diagnostics)==(incomplete?1:full));ApxValue *first=apx_json_item(diagnostics,0);assert(!strcmp(apx_json_string(apx_json_get(first,"code")),incomplete?"P006":"H001"));if(incomplete)assert(strstr(apx_json_string(apx_json_get(first,"message")),"incomplete"));}
static char source[65537],payload[150000];
static void source_case(unsigned locals,unsigned holes,unsigned depth){size_t n=(size_t)snprintf(source,sizeof source,"M many\nF main");if(depth){for(unsigned i=0;i<locals;i++){n+=(size_t)snprintf(source+n,sizeof source-n," binding%04u:",i);for(unsigned j=0;j<depth;j++)source[n++]='[';memcpy(source+n,"i64",3);n+=3;for(unsigned j=0;j<depth;j++)source[n++]=']';}}n+=(size_t)snprintf(source+n,sizeof source-n,"->i64\n");if(!depth)for(unsigned i=0;i<locals;i++)n+=(size_t)snprintf(source+n,sizeof source-n,"  L binding%04u %u\n",i,i);for(unsigned i=0;i<holes;i++){memcpy(source+n,"  A _\n",6);n+=6;}memcpy(source+n,"  R 0\n",7);assert(n+6<sizeof source);}
static void probe(const char *directory,unsigned locals,unsigned holes,unsigned depth,int cli_incomplete,int mcp_incomplete){source_case(locals,holes,depth);char *canonical=NULL,*raw=NULL;assert(apx_check_source(source,&canonical,&raw)==1&&canonical&&raw);size_t count=0;for(const char *p=raw;(p=strstr(p,"\"code\":\"H001\""));p++)count++;assert(count==holes);size_t raw_bytes=strlen(raw);if(cli_incomplete)assert(raw_bytes>2u*1024u*1024u);else assert(raw_bytes<2u*1024u*1024u);free(canonical);free(raw);
    char *output=invoke("check",source,directory,2);ApxValue *checked=apx_json_parse(output,strlen(output));check_diagnostics(checked,holes,cli_incomplete);free(output);apx_json_reset();
    ApxValue *text=apx_string(source,(int64_t)strlen(source));char *quoted=apx_json_encode(text);assert(quoted);int n=snprintf(payload,sizeof payload,"{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\"}\n{\"jsonrpc\":\"2.0\",\"method\":\"notifications/initialized\"}\n{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/call\",\"params\":{\"name\":\"apodexis_check\",\"arguments\":{\"source\":%s}}}\n{\"jsonrpc\":\"2.0\",\"id\":3,\"method\":\"ping\"}\n",quoted);assert(n>0&&(size_t)n<sizeof payload);free(quoted);apx_json_reset();output=invoke("mcp",payload,directory,0);ApxValue *result=result_at(output,2),*response=apx_json_get(result,"structuredContent");check_diagnostics(response,holes,mcp_incomplete);assert(apx_json_integer(apx_json_get(result,"isError"))==1);assert(apx_json_length(apx_json_get(response,"typed_holes"))==(mcp_incomplete?0:holes));assert(result_at(output,3));free(output);apx_json_reset();printf("diagnostic transport: locals=%u holes=%u type_depth=%u raw=%zu bytes CLI=%s MCP=%s PASS\n",locals,holes,depth,raw_bytes,cli_incomplete?"explicit incomplete":"complete",mcp_incomplete?"explicit incomplete":"complete");}
int main(void){char directory[]=".build/diagnostic-transport-XXXXXX";assert(mkdtemp(directory));probe(directory,100,100,0,0,0);probe(directory,500,500,0,1,1);probe(directory,24,100,40,0,1);char path[4096];snprintf(path,sizeof path,"%s/source",directory);unlink(path);snprintf(path,sizeof path,"%s/output",directory);unlink(path);assert(!rmdir(directory));puts("native CLI/MCP diagnostic delivery: ordinary collection, raw budget and expanded scope budget never silently empty PASS");return 0;}
